    const box = h('div', { class: 'casepart' }, h('div', { class: 'sp' }, h('span', { class: 'pill c' }, tE('engine.ex.casePart', { n: i + 1, of: ex.parts.length })), ' ', h('span', { html: fmt(p.q) })), w.el);
