        if (!ok) { const r = st.hits(p.x, p.y)[0]; if (r) { st.outline(r.id, 'wrong'); if (ex.why?.[r.id]) notes.push(h('div', { html: `❌ <b>${esc(r.label || r.id)}</b>: ` + fmt(ex.why[r.id]) })); } }
