    Object.values(badges).forEach(b => b.remove());
    picks.forEach((r, i) => { const [x, y] = rCenter(r); badges[r.id] = h('span', { class: 'vx-num vx-step', style: st.pos(x, y) }, i + 1); st.layer.append(badges[r.id]); });
