      slots.forEach(s => { const r = res(s); s.ctl.readOnly = true; s.ctl.classList.add(r.ok ? 'right' : 'wrong'); st.outline(s.r.id, r.ok ? 'right' : 'wrong'); });
      st.below.append(vResults(slots.map(s => ({ k: s.k, r: s.r, ...res(s), given: s.ctl.value.trim() }))));
