  const crossover = (f, ht, hr) => 4 * Math.PI * ht * hr * f / C0;
  const twoRay = (d, f, ht, hr) => (d < crossover(f, ht, hr) ? fspl(d, f) : 40 * log10(d) - 20 * log10(ht * hr));
