      if (earlier.length) det.append(h('div', { class: 'lbl kmaplv' }, tE('engine.kmap.earlier')), h('ul', { class: 'tiny' }, ...earlier.map(p => h('li', {}, F(p.text), ' — ', h('i', {}, String(p.taughtIn))))));
